/**
 * Notification inbox.
 *
 * Owner D. The list component receives the two mutations as props rather than
 * importing the actions itself — that keeps `src/components/domain` free of any
 * dependency on the action layer.
 *
 * Must call (do not reimplement): can
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { NotificationList } from "@/components/domain/notification/notification-list";
import { markAllNotificationsReadAction } from "@/actions/notifications/mark-all-read";
import { markNotificationReadAction } from "@/actions/notifications/mark-read";
import { can } from "@/lib/permissions";
import { listNotifications } from "@/server/services/notification-service";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import type { NotificationId } from "@/types/common";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Inbox",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const allowed = can(actor, "notification:read", {
    kind: "notification",
    orgId: org.id,
    recipientId: actor.userId,
  });
  if (!allowed) {
    notFound();
  }

  const pagination = searchParamsPaginationSchema.parse(search);
  const unreadOnly = search.filter === "unread";

  const page = await listNotifications(actor, {
    orgId: org.id,
    recipientId: actor.userId,
    unreadOnly,
    limit: pagination.perPage,
    cursor: pagination.cursor ?? null,
  });

  async function markRead(notificationId: NotificationId): Promise<void> {
    "use server";
    await markNotificationReadAction({ orgId: org.id, notificationId });
  }

  async function markAllRead(): Promise<void> {
    "use server";
    await markAllNotificationsReadAction({ orgId: org.id });
  }

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">Inbox</h1>
        <p className="mt-1 text-sm text-slate-600">
          {page.total} {unreadOnly ? "unread" : "total"} notifications
        </p>
      </header>

      <NotificationList
        notifications={page.items}
        onMarkRead={markRead}
        onMarkAllRead={markAllRead}
      />
    </div>
  );
}
----PANEL
/**
 * Notification panel rendered into the `@panel` slot.
 *
 * Owner D. Matches `/[orgSlug]/notifications`, so opening notifications keeps
 * whatever page is already in the main column instead of navigating away from
 * it — the reason this slot exists at all.
 */

import Link from "next/link";
import { can } from "@/lib/permissions";
import { listNotifications } from "@/server/services/notification-service";
import { loadTenantContext } from "../../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

const PANEL_NOTIFICATION_LIMIT = 20;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const allowed = can(actor, "notification:read", {
    kind: "notification",
    orgId: org.id,
    recipientId: actor.userId,
  });
  if (!allowed) {
    return null;
  }

  const page = await listNotifications(actor, {
    orgId: org.id,
    recipientId: actor.userId,
    unreadOnly: search.unread === "1",
    limit: PANEL_NOTIFICATION_LIMIT,
  });

  return (
    <section className="p-6">
      <div className="flex items-baseline justify-between">
        <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
          Notifications
        </h2>
        <Link href={`/${orgSlug}/inbox`} className="text-xs text-indigo-600">
          Open inbox
        </Link>
      </div>

      <ul className="mt-4 space-y-3">
        {page.items.map((notification) => (
          <li key={notification.id}>
            <Link href={notification.href} className="block text-sm">
              <span
                className={
                  notification.readAt === null
                    ? "font-medium text-slate-900"
                    : "text-slate-600"
                }
              >
                {notification.title}
              </span>
              <span className="mt-0.5 block text-xs text-slate-500">
                {notification.body}
              </span>
            </Link>
          </li>
        ))}
      </ul>
    </section>
  );
}
----SETTINGS
/**
 * Notification preference matrix.
 *
 * Owner D. One row per `NotificationKind`, three columns (in-app, email,
 * digest). The digest column only means anything while the `digest_email` flag
 * is on, so the flag decides whether it is rendered at all.
 *
 * Must call (do not reimplement): isEnabled
 */

import type { Metadata } from "next";
import { updateNotificationPreferenceAction } from "@/actions/notifications/update-preferences";
import { NotificationPreferencesForm } from "@/components/domain/notification/notification-preferences-form";
import { isEnabled } from "@/lib/feature-flags";
import { listPreferences } from "@/server/repositories/notification-preference-repository";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { loadTenantContext } from "../../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Notification preferences",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor, flags } = await loadTenantContext(orgSlug);

  const digestEnabled = isEnabled("digest_email", buildFlagContext(actor, org));

  // Preferences are per-user rows with no rule attached; `NotificationService`
  // owns the write path, and the read goes straight to the repository.
  const preferences = await listPreferences(org.id, actor.userId);

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-xl font-semibold tracking-tight">Notifications</h1>
        <p className="mt-1 text-sm text-slate-600">
          How you want to hear about things happening in {org.name}.
          {digestEnabled
            ? " Anything marked digest-only is bundled into one email a day."
            : " The daily digest is not part of this plan."}
        </p>
      </header>

      <NotificationPreferencesForm
        orgId={org.id}
        userId={actor.userId}
        preferences={preferences}
        flags={flags}
        onSubmit={updateNotificationPreferenceAction}
      />
    </div>
  );
}
---ACTIONS-ERR
/**
 * Wrapper shared by every Server Action: parses with a Zod schema, resolves the
 * `Actor`, maps thrown domain errors to an `AppErrorShape` and revalidates the
 * affected tags.
 *
 * Owner D. Every mutation in `src/actions/**` funnels through here so the four
 * things each one must do — validate, authenticate, translate errors,
 * revalidate — happen in exactly one place.
 *
 * Must call (do not reimplement): getActor, toActionResult, revalidateTagged
 */

import { getActor, requireActorFor } from "@/lib/actor";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { ZodType } from "zod";
import { UnauthorizedActionError } from "./action-errors";

/** The body of an action: already-validated input plus the resolved principal. */
export type ActionHandler = (input: unknown, actor: Actor) => Promise<unknown>;

export type ActionOptions = {
  /**
   * When `true` (the default) the organization is taken from the parsed input —
   * either an `orgSlug` or an `orgId` field. When `false` the action does not
   * name an organization and the session's active org is used instead.
   */
  requireOrg?: boolean;
  /** Static cache tags invalidated once the handler resolves. */
  revalidate?: readonly string[];
  /** cacheLife profile handed to `revalidateTag` — required in Next 16. */
  cacheProfile?: string;
};

type OrgBearingInput = { orgSlug?: unknown; orgId?: unknown };

/**
 * Resolves the actor for one action call.
 *
 * `getActor(orgSlug)` is the primary path because most mutations are dispatched
 * from a `[orgSlug]` route; actions whose payload carries the branded `orgId`
 * instead resolve through `requireActorFor()`.
 */
async function resolveActorFor(input: unknown, fromInput: boolean): Promise<Actor> {
  if (fromInput && typeof input === "object" && input !== null) {
    const record = input as OrgBearingInput;
    if (typeof record.orgSlug === "string" && record.orgSlug.length > 0) {
      return getActor(record.orgSlug);
    }
    if (typeof record.orgId === "string" && record.orgId.length > 0) {
      return requireActorFor(record.orgId as OrgId);
    }
  }

  const principal = await getSessionPrincipal();
  if (principal === null || principal.activeOrgId === null) {
    throw new UnauthorizedActionError();
  }
  return requireActorFor(principal.activeOrgId);
}

/** Adds the monotonic token `useActionState` uses to tell two results apart. */
function stamp<T>(result: ActionResult<T>): ActionResult<T> {
  const submittedAt = new Date().toISOString();
  return result.ok
    ? { ok: true, data: result.data, submittedAt }
    : { ok: false, error: result.error, submittedAt };
}

export function withAction<TSchema extends ZodType, TData>(
  schema: TSchema,
  handler: ActionHandler,
  options: ActionOptions = {},
): (raw: unknown) => Promise<ActionResult<TData>> {
  return async function runAction(raw: unknown): Promise<ActionResult<TData>> {
    const parsed = schema.safeParse(raw);
    if (!parsed.success) {
      return stamp(toActionResult(parsed.error));
    }

    try {
      const actor = await resolveActorFor(parsed.data, options.requireOrg !== false);
      const data = (await handler(parsed.data, actor)) as TData;

      const tags = options.revalidate ?? [];
      if (tags.length > 0) {
        revalidateTagged(tags, options.cacheProfile ?? CACHE_PROFILES.minutes);
      }

      return stamp({ ok: true, data });
    } catch (error) {
      return stamp(toActionResult(error));
    }
  };
}

