import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import * as issueService from "@/server/services/issue-service";
import * as notifSvc from "@/server/services/notification-service";
import * as searchSvc from "@/server/services/search-service";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId } from "@/types/common";

let cleanup: () => void;
let t: Tenant;
const all = (actor: Tenant["actors"]["owner"], recipient: Tenant["userIds"]["owner"]) =>
  notifSvc.listNotifications(actor, { orgId: t.org.id, recipientId: recipient, unreadOnly: false, limit: 100, cursor: null });

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("verify", "growth");
});
afterAll(() => cleanup());

describe("verify", () => {
  it("member.joined → owner told, joiner not", async () => {
    await emit("member.joined", { orgId: t.org.id, actorId: t.userIds.viewer, occurredAt: new Date().toISOString() as never, memberId: "m" as never, userId: t.userIds.viewer, role: "viewer" });
    const owner = await all(t.actors.owner, t.userIds.owner);
    const viewer = await all(t.actors.viewer, t.userIds.viewer);
    console.log("OWNER joined:", owner.items.filter(i => i.kind === "member_joined").map(i => i.href));
    expect(owner.items.some(i => i.kind === "member_joined")).toBe(true);
    expect(viewer.items.some(i => i.kind === "member_joined")).toBe(false);
  });

  it("assigned at creation, status change, self-action, no-assignee", async () => {
    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "A", assigneeId: t.userIds.admin } as never));
    const adminItems = await all(t.actors.admin, t.userIds.admin);
    console.log("ADMIN after create:", adminItems.items.map(i => [i.kind, i.href]));
    expect(adminItems.items.some(i => i.kind === "issue_assigned" && i.href.endsWith(`/issues/${issue.number}`))).toBe(true);

    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issue.id, status: "in_progress" } as never);
    const adminAfter = await all(t.actors.admin, t.userIds.admin);
    const memberAfter = await all(t.actors.member, t.userIds.member);
    expect(adminAfter.items.some(i => i.kind === "issue_status_changed")).toBe(true);
    expect(memberAfter.items.some(i => i.kind === "issue_status_changed")).toBe(false);

    // Moving it as the assignee themselves: nobody told.
    const before = (await all(t.actors.member, t.userIds.member)).total;
    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: issue.id, status: "done" } as never);
    expect((await all(t.actors.member, t.userIds.member)).total).toBe(before);
    expect((await all(t.actors.admin, t.userIds.admin)).items.filter(i => i.kind === "issue_status_changed").length).toBe(1);
  });

  it("search hits and inbox ownership, mark-all scope, in-app filter", async () => {
    const hits = await searchSvc.search(t.actors.member, { orgId: t.org.id, q: "A", limit: 25, cursor: null } as never);
    console.log("HITS:", hits.items.map(h => [h.kind, h.href]));
    await expect(notifSvc.listNotifications(t.actors.member, { orgId: t.org.id, recipientId: t.userIds.owner, unreadOnly: false, limit: 25, cursor: null })).rejects.toThrow();
    await expect(notifSvc.markAllRead(t.actors.admin, t.org.id)).resolves.toBeGreaterThanOrEqual(0);
    const ownerUnread = await notificationRepo.countUnread(t.org.id, t.userIds.owner);
    expect(ownerUnread).toBeGreaterThanOrEqual(1);

    // email-only preference: not in inbox
    await notifSvc.updatePreference(t.actors.member, { orgId: t.org.id, userId: t.userIds.member, kind: "issue_overdue", inApp: false, email: true, digestOnly: false } as never);
    await notifSvc.notify(t.org.id, "issue_overdue", [t.userIds.member], { title: "od", body: "b", href: "/x", actorId: null });
    const memberList = await all(t.actors.member, t.userIds.member);
    expect(memberList.items.some(i => i.kind === "issue_overdue")).toBe(false);
    await expect(notifSvc.updatePreference(t.actors.member, { orgId: t.org.id, userId: t.userIds.owner, kind: "issue_overdue", inApp: false, email: true, digestOnly: false } as never)).rejects.toThrow();
  });

  it("plan limit alerts dedupe until read", async () => {
    const seatAlerts = async () => (await all(t.actors.owner, t.userIds.owner)).items.filter(i => i.kind === "plan_limit_reached");
    const refuse = () => emit("billing.limit_exceeded", { orgId: t.org.id, actorId: t.userIds.member, occurredAt: new Date().toISOString() as never, resource: "seats", limit: 3, used: 3 });
    await refuse();
    await refuse();
    expect((await seatAlerts()).length).toBe(1);
    await notifSvc.markRead(t.actors.owner, { orgId: t.org.id, notificationId: (await seatAlerts())[0]!.id });
    await refuse();
    expect((await seatAlerts()).length).toBe(2);
    expect((await seatAlerts())[0]!.href).toBe(`/${t.org.slug}/settings/billing`);
    // owner who tried is still told
    await emit("billing.limit_exceeded", { orgId: t.org.id, actorId: t.userIds.owner, occurredAt: new Date().toISOString() as never, resource: "projects", limit: 3, used: 3 });
    expect((await seatAlerts()).length).toBe(2);
    expect((await all(t.actors.owner, t.userIds.owner)).items.some(i => i.kind === "plan_limit_reached" && i.title === "Project limit reached")).toBe(true);
  });
});
